#region CargoShipV3
const string VERSION="3.2.0";/**CargoShipV3-Cargo Drone v3*Protocol:v3(PMV4 integration)**A simple cargo truck.Flies where told,docks,signals,*waits for PMV4 to handle cargo transfers,then flies home.*No manifest knowledge.No cargo handling.**While docked:thrusters off(no idle H2 burn),batteries on*Recharge,H2 tanks stockpiled.Before any SAM trigger:systems*restored,then a pre-flight check(thrusters,batteries,*dampeners,fuel)gates the launch.Refused assignments are*NACK'd back to the SupplyStation so missions unwind cleanly.*/const string STATE_IDLE="IDLE";const string STATE_MISSION="MISSION";const string STATE_DOCKED="DOCKED";const string STATE_RETURNING="RETURNING";const string STATE_DOCKED_HOME="DOCKED_HOME";const string STATE_UNDOCK_PREP="UNDOCK_PREP";const string CH_AVAILABLE="DRONE_AVAILABLE";const string CH_ASSIGN="DRONE_ASSIGN";const string CH_ARRIVED="DRONE_ARRIVED";const string CH_NACK="DRONE_NACK";const string CH_CARGO_STATUS="PMV4_CARGO_STATUS";string droneId="";string homeStation="";List<string>tags=new List<string>();string autopilotPBName="";string statusLcdTag="[STATUS]";int minBatteryPct=90;int minH2Pct=90;bool manageH2Stockpile=true;bool manageThrusters=true;bool manageBatteries=true;int undockPrepTicks=2;string currentState=STATE_IDLE;string missionDestination="";string missionHomeConnector="";bool wasDocked=false;bool transferCompleted=false;string undockTarget="";string undockNextState="";int undockPrepTicksRemaining=0;bool validationFailed=false;bool samRetryPending=false;List<string>validationErrors=new List<string>();IMyProgrammableBlock autopilotPB=null;StringBuilder statusLog=new StringBuilder();IMyBroadcastListener assignListener;IMyBroadcastListener cargoStatusListener;int availableTicks=0;const int AVAILABLE_INTERVAL=18;public Program(){if(string.IsNullOrWhiteSpace(Me.CustomData)){Me.CustomData=GetDefaultConfig();Echo("=== FIRST-TIME SETUP ===");Echo("Edit CustomData and recompile.");Runtime.UpdateFrequency=UpdateFrequency.None;return;}LoadConfig();FindAutopilotPB();RunValidation();assignListener=IGC.RegisterBroadcastListener(CH_ASSIGN);assignListener.SetMessageCallback(CH_ASSIGN);cargoStatusListener=IGC.RegisterBroadcastListener(CH_CARGO_STATUS);cargoStatusListener.SetMessageCallback(CH_CARGO_STATUS);Runtime.UpdateFrequency=UpdateFrequency.Update100;RecoverState();}public void Save(){PersistState();}public void Main(string argument,UpdateType updateSource){statusLog.Clear();LogStatus($"CargoShip v{VERSION}");LogStatus("====================");if(!string.IsNullOrEmpty(argument)){string arg=argument.Trim().ToUpperInvariant();if(arg=="RESET"){Storage="";currentState=STATE_IDLE;missionDestination="";missionHomeConnector="";Echo("State cleared.");}else if(arg=="RELOAD"){LoadConfig();FindAutopilotPB();RunValidation();LogStatus("Config reloaded.");}}if(validationFailed){LogStatus("\n[CRITICAL ERRORS]");foreach(var err in validationErrors)LogStatus(err);LogStatus("\nFix errors and recompile.");UpdateDisplays();return;}foreach(var err in validationErrors)if(err.Contains("[WARNING]"))LogStatus(err);if(samRetryPending){samRetryPending=false;if(currentState==STATE_MISSION&&!string.IsNullOrEmpty(missionDestination)){TriggerAutopilot(missionDestination);}else if(currentState==STATE_RETURNING){TriggerAutopilot(homeStation);}}var connector=GetShipConnector();bool isDocked=false;string currentStationId="";if(connector!=null&&connector.Status==MyShipConnectorStatus.Connected){isDocked=true;currentStationId=GetStationId(connector);}bool justDocked=isDocked&&!wasDocked;if(!isDocked){SetThrusters(true);SetBatteryRecharge(false);SetH2Stockpile(false);}ProcessAssignments();ProcessTransferComplete();switch(currentState){case STATE_IDLE:HandleIdle(isDocked,currentStationId);break;case STATE_MISSION:HandleMission(isDocked,justDocked,currentStationId);break;case STATE_DOCKED:HandleDocked(currentStationId);break;case STATE_RETURNING:HandleReturning(isDocked,justDocked,currentStationId);break;case STATE_DOCKED_HOME:HandleDockedHome();
break;case STATE_UNDOCK_PREP:HandleUndockPrep(currentStationId);break;}wasDocked=isDocked;UpdateDisplays();}void HandleIdle(bool isDocked,string stationId){if(!isDocked){LogStatus("\nNot docked. Waiting...");return;}LogStatus($"\nDocked at: {stationId}");SetH2Stockpile(true);SetThrusters(false);SetBatteryRecharge(true);if(!FuelLevelsOK()){LogStatus($"Status: IDLE - REFUELING - {FuelStatusLine()}");LogStatus($"  Target: Battery >= {minBatteryPct}%, H2 >= {minH2Pct}%");LogStatus("Holding AVAILABLE broadcast until fueled.");availableTicks=0;return;}LogStatus("Status: IDLE - Ready for assignment");availableTicks++;if(availableTicks>=AVAILABLE_INTERVAL){BroadcastAvailability(stationId);availableTicks=0;}LogStatus($"Broadcasting AVAILABLE in {AVAILABLE_INTERVAL - availableTicks} ticks");}void HandleMission(bool isDocked,bool justDocked,string stationId){LogStatus($"\nMission: fly to {missionDestination}");if(justDocked){LogStatus($"Docked at: {stationId}");currentState=STATE_DOCKED;PersistState();SetH2Stockpile(true);SetThrusters(false);SetBatteryRecharge(true);SendArrived();LogStatus("Sent ARRIVED -- waiting for cargo transfer...");}else if(!isDocked){LogStatus("In transit...");}}void HandleDocked(string stationId){LogStatus($"\nDocked at: {stationId}");if(!transferCompleted){LogStatus("Waiting for cargo transfer...");return;}if(!FuelLevelsOK()){LogStatus("Cargo transfer complete.");LogStatus($"REFUELING -- {FuelStatusLine()}");LogStatus($"  Target: Battery >= {minBatteryPct}%, H2 >= {minH2Pct}%");return;}transferCompleted=false;StartUndockPrep(missionHomeConnector,STATE_RETURNING);LogStatus($"Fueled. Preparing undock for return to {missionHomeConnector}");}void HandleReturning(bool isDocked,bool justDocked,string stationId){LogStatus($"\nReturning to: {missionHomeConnector}");if(justDocked){LogStatus($"Docked at: {stationId}");currentState=STATE_DOCKED_HOME;PersistState();SetH2Stockpile(true);SetThrusters(false);SetBatteryRecharge(true);SendArrived();LogStatus("Sent ARRIVED -- waiting for cargo transfer...");}else if(!isDocked){LogStatus("In transit...");}}void StartUndockPrep(string target,string nextState){SetBatteryRecharge(false);SetThrusters(true);SetH2Stockpile(false);undockTarget=target;undockNextState=nextState;bool hasH2=GetH2Tanks().Count>0;undockPrepTicksRemaining=hasH2?undockPrepTicks:0;currentState=STATE_UNDOCK_PREP;PersistState();if(undockPrepTicksRemaining<=0){HandleUndockPrep("");}}void HandleUndockPrep(string stationId){LogStatus($"\nDocked at: {stationId}");LogStatus($"UNDOCK PREP -- {FuelStatusLine()}");if(undockPrepTicksRemaining>0){LogStatus($"  H2 settle: {undockPrepTicksRemaining} tick(s) remaining before SAM");undockPrepTicksRemaining--;return;}string holdReason=PreflightCheck(true);if(!string.IsNullOrEmpty(holdReason)){LogStatus($"  PREFLIGHT HOLD: {holdReason}");return;}SetDampeners(true);currentState=string.IsNullOrEmpty(undockNextState)?STATE_IDLE:undockNextState;PersistState();TriggerAutopilot(undockTarget);LogStatus($"Preflight passed. Triggered SAM: {undockTarget}");undockTarget="";undockNextState="";}void HandleDockedHome(){LogStatus($"\nDocked at home: {homeStation}");if(!transferCompleted){LogStatus("Waiting for cargo transfer...");return;}if(!FuelLevelsOK()){LogStatus("Cargo transfer complete.");LogStatus($"REFUELING -- {FuelStatusLine()}");LogStatus($"  Target: Battery >= {minBatteryPct}%, H2 >= {minH2Pct}%");return;}currentState=STATE_IDLE;missionDestination="";missionHomeConnector="";transferCompleted=false;PersistState();LogStatus("Fueled. Ready for next assignment.");}void ProcessAssignments(){while(assignListener.HasPendingMessage){var message=assignListener.AcceptMessage();var data=message.Data.ToString();var parts=data.Split('|');if(parts.Length<3||parts[0]!="ASSIGN")continue;if(parts[1]!=droneId)continue;string dest=parts[2];if((currentState==STATE_MISSION||currentState==STATE_UNDOCK_PREP)&&missionDestination==dest)continue;if(currentState!=STATE_IDLE){SendNack(dest,"busy: "+currentState);
continue;}if(!FuelLevelsOK()){SendNack(dest,"refueling: "+FuelStatusLine());continue;}string unfit=PreflightCheck(false);if(!string.IsNullOrEmpty(unfit)){SendNack(dest,unfit);continue;}missionDestination=dest;missionHomeConnector=parts.Length>=4?parts[3]:homeStation;availableTicks=0;StartUndockPrep(missionDestination,STATE_MISSION);LogStatus($"\n*** ASSIGNED: fly to {missionDestination} (prep undock) ***");}}void SendNack(string destination,string reason){IGC.SendBroadcastMessage(CH_NACK,$"ASSIGN_NACK|{droneId}|{destination}|{reason}");LogStatus($"Assignment NACK'd: {reason}");}void ProcessTransferComplete(){while(cargoStatusListener.HasPendingMessage){var message=cargoStatusListener.AcceptMessage();var data=message.Data.ToString();var parts=data.Split('|');if(parts.Length<2||parts[0]!="TRANSFER_COMPLETE")continue;string droneGridName=GetDockableGridName();if(parts[1]!=droneGridName)continue;if(currentState==STATE_DOCKED||currentState==STATE_DOCKED_HOME){transferCompleted=true;PersistState();LogStatus("PMV4 signaled transfer complete.");}}}void PersistState(){string xferFlag=transferCompleted?"1":"0";switch(currentState){case STATE_MISSION:Storage=STATE_MISSION+"|"+missionDestination+"|"+missionHomeConnector;break;case STATE_DOCKED:Storage=STATE_DOCKED+"|"+missionDestination+"|"+missionHomeConnector+"|"+xferFlag;break;case STATE_RETURNING:Storage=STATE_RETURNING+"|"+missionHomeConnector;break;case STATE_DOCKED_HOME:Storage=STATE_DOCKED_HOME+"|"+xferFlag;break;case STATE_UNDOCK_PREP:Storage=STATE_UNDOCK_PREP+"|"+undockTarget+"|"+undockNextState+"|"+missionDestination+"|"+missionHomeConnector;break;default:Storage=STATE_IDLE;break;}}void RecoverState(){string saved=Storage??"";if(string.IsNullOrEmpty(saved)||saved==STATE_IDLE){currentState=STATE_IDLE;return;}var parts=saved.Split('|');string state=parts[0];if(state==STATE_MISSION&&parts.Length>=3){missionDestination=parts[1];missionHomeConnector=parts[2];currentState=STATE_MISSION;SetBatteryRecharge(false);SetThrusters(true);SetH2Stockpile(false);if(!TriggerAutopilot(missionDestination))samRetryPending=true;}else if(state==STATE_DOCKED&&parts.Length>=3){missionDestination=parts[1];missionHomeConnector=parts[2];currentState=STATE_DOCKED;transferCompleted=parts.Length>=4&&parts[3]=="1";if(!transferCompleted)SendArrived();}else if(state==STATE_RETURNING&&parts.Length>=2){missionHomeConnector=parts[1];currentState=STATE_RETURNING;SetBatteryRecharge(false);SetThrusters(true);SetH2Stockpile(false);if(!TriggerAutopilot(missionHomeConnector))samRetryPending=true;}else if(state==STATE_DOCKED_HOME){currentState=STATE_DOCKED_HOME;transferCompleted=parts.Length>=2&&parts[1]=="1";if(!transferCompleted)SendArrived();}else if(state==STATE_UNDOCK_PREP&&parts.Length>=5){undockTarget=parts[1];undockNextState=parts[2];missionDestination=parts[3];missionHomeConnector=parts[4];currentState=STATE_UNDOCK_PREP;undockPrepTicksRemaining=undockPrepTicks;SetBatteryRecharge(false);SetThrusters(true);SetH2Stockpile(false);}else{currentState=STATE_IDLE;}Echo($"Recovered state: {currentState}");}void BroadcastAvailability(string currentStationId){var tagsString=string.Join(",",tags);double capacityL=GetCargoCapacityL();string gridName=GetDockableGridName();var message=$"AVAILABLE|{droneId}|{homeStation}|{currentStationId}|{tagsString}|{capacityL:F0}|{gridName}";IGC.SendBroadcastMessage(CH_AVAILABLE,message);}void SendArrived(){var message=$"ARRIVED|{droneId}|{GetDockableGridName()}";IGC.SendBroadcastMessage(CH_ARRIVED,message);}bool TriggerAutopilot(string connectorName){if(autopilotPB==null){LogStatus("ERROR: SAM PB not found");return false;}string command="GO "+connectorName;if(!autopilotPB.TryRun(command)){LogStatus("ERROR: Failed to trigger SAM");return false;}LogStatus($">>> SAM: {command}");return true;}IMyShipConnector GetShipConnector(){var connectors=new List<IMyShipConnector>();GridTerminalSystem.GetBlocksOfType(connectors,c=>c.IsSameConstructAs(Me));return connectors.Count>0?connectors[0]:null;}string GetDockableGridName(){var conn=GetShipConnector();
if(conn!=null)return conn.CubeGrid.CustomName;return Me.CubeGrid.CustomName;}string GetStationId(IMyShipConnector connector){var other=connector.OtherConnector;if(other!=null){var customData=other.CustomData;if(!string.IsNullOrEmpty(customData)){var lines=customData.Split('\n');foreach(var line in lines){var trimmed=line.Trim();if(trimmed.StartsWith("StationID=")){var val=trimmed.Substring("StationID=".Length).Trim();if(!string.IsNullOrEmpty(val))return val;}}}return other.CubeGrid.CustomName;}return"";}double GetCargoCapacityL(){var containers=new List<IMyCargoContainer>();GridTerminalSystem.GetBlocksOfType(containers,c=>c.IsSameConstructAs(Me));double totalL=0;foreach(var c in containers){totalL+=(double)c.GetInventory(0).MaxVolume*1000.0;}return totalL;}bool FuelLevelsOK(){int batPct=GetBatteryChargePct();int h2Pct=GetH2TankFillPct();bool batOK=minBatteryPct<=0||batPct<0||batPct>=minBatteryPct;bool h2OK=minH2Pct<=0||h2Pct<0||h2Pct>=minH2Pct;return batOK&&h2OK;}string FuelStatusLine(){int batPct=GetBatteryChargePct();int h2Pct=GetH2TankFillPct();string batStr=batPct<0?"n/a":batPct+"%";string h2Str=h2Pct<0?"n/a":h2Pct+"%";return"Battery: "+batStr+" | H2: "+h2Str;}int GetBatteryChargePct(){var batteries=new List<IMyBatteryBlock>();GridTerminalSystem.GetBlocksOfType(batteries,b=>b.IsSameConstructAs(Me));if(batteries.Count==0)return-1;float stored=0,max=0;foreach(var b in batteries){stored+=b.CurrentStoredPower;max+=b.MaxStoredPower;}if(max<=0)return-1;return(int)(stored/max*100f);}int GetH2TankFillPct(){var tanks=GetH2Tanks();if(tanks.Count==0)return-1;double filled=0,cap=0;foreach(var t in tanks){filled+=(double)t.FilledRatio*t.Capacity;cap+=t.Capacity;}if(cap<=0)return-1;return(int)(filled/cap*100.0);}List<IMyGasTank>GetH2Tanks(){var tanks=new List<IMyGasTank>();GridTerminalSystem.GetBlocksOfType(tanks,t=>t.IsSameConstructAs(Me)&&t.BlockDefinition.SubtypeId.IndexOf("Hydrogen",StringComparison.OrdinalIgnoreCase)>=0);return tanks;}bool?lastStockpileState=null;void SetH2Stockpile(bool stockpile){if(!manageH2Stockpile)return;if(lastStockpileState==stockpile)return;foreach(var t in GetH2Tanks())t.Stockpile=stockpile;lastStockpileState=stockpile;}List<IMyThrust>GetThrusters(){var thrusters=new List<IMyThrust>();GridTerminalSystem.GetBlocksOfType(thrusters,t=>t.IsSameConstructAs(Me));return thrusters;}bool?lastThrustersOn=null;void SetThrusters(bool on){if(!manageThrusters)return;if(lastThrustersOn==on)return;foreach(var t in GetThrusters())t.Enabled=on;lastThrustersOn=on;}List<IMyBatteryBlock>GetBatteries(){var batteries=new List<IMyBatteryBlock>();GridTerminalSystem.GetBlocksOfType(batteries,b=>b.IsSameConstructAs(Me));return batteries;}bool?lastBatteriesRecharge=null;void SetBatteryRecharge(bool recharge){if(!manageBatteries)return;if(lastBatteriesRecharge==recharge)return;var batteries=GetBatteries();for(int i=0;i<batteries.Count;i++){if(recharge&&i==0){batteries[i].ChargeMode=ChargeMode.Auto;continue;}batteries[i].ChargeMode=recharge?ChargeMode.Recharge:ChargeMode.Auto;}lastBatteriesRecharge=recharge;}void SetDampeners(bool on){var ctrls=new List<IMyShipController>();GridTerminalSystem.GetBlocksOfType(ctrls,c=>c.IsSameConstructAs(Me));foreach(var c in ctrls)c.DampenersOverride=on;}string PreflightCheck(bool thorough){var thrusters=GetThrusters();if(thrusters.Count==0)return"no thrusters on grid";foreach(var t in thrusters)if(!t.IsFunctional)return"thruster damaged: "+t.CustomName;if(thorough){bool anyOn=false;foreach(var t in thrusters)if(t.Enabled){anyOn=true;break;}if(!anyOn)return"all thrusters disabled";foreach(var b in GetBatteries())if(b.ChargeMode==ChargeMode.Recharge)return"battery in Recharge: "+b.CustomName;}if(!FuelLevelsOK())return"fuel low: "+FuelStatusLine();return"";}void FindAutopilotPB(){autopilotPB=null;if(string.IsNullOrEmpty(autopilotPBName))return;var pbs=new List<IMyProgrammableBlock>();GridTerminalSystem.GetBlocksOfType(pbs,pb=>pb.IsSameConstructAs(Me)&&pb.CustomName.Contains(autopilotPBName));if(pbs.Count>0)autopilotPB=pbs[0];
}void LoadConfig(){var ini=new MyIni();if(!ini.TryParse(Me.CustomData)){Echo("WARNING: Failed to parse CustomData");}const string S="CargoShip";droneId=ini.Get(S,"DroneID").ToString("").Trim();homeStation=ini.Get(S,"HomeStation").ToString("").Trim();autopilotPBName=ini.Get(S,"AutopilotPBName").ToString("").Trim();statusLcdTag=ini.Get(S,"StatusLcdTag").ToString("[STATUS]").Trim();minBatteryPct=ini.Get(S,"MinBatteryPercent").ToInt32(90);minH2Pct=ini.Get(S,"MinH2Percent").ToInt32(90);manageH2Stockpile=ini.Get(S,"ManageH2Stockpile").ToBoolean(true);manageThrusters=ini.Get(S,"ManageThrusters").ToBoolean(true);manageBatteries=ini.Get(S,"ManageBatteries").ToBoolean(true);undockPrepTicks=ini.Get(S,"UndockPrepTicks").ToInt32(2);if(undockPrepTicks<0)undockPrepTicks=0;if(minBatteryPct<0)minBatteryPct=0;if(minBatteryPct>100)minBatteryPct=100;if(minH2Pct<0)minH2Pct=0;if(minH2Pct>100)minH2Pct=100;tags.Clear();string tagsStr=ini.Get(S,"Tags").ToString("").Trim();if(!string.IsNullOrEmpty(tagsStr)){var parts=tagsStr.Split(',');foreach(var t in parts){string trimmed=t.Trim().ToUpperInvariant();if(!string.IsNullOrEmpty(trimmed))tags.Add(trimmed);}}if(string.IsNullOrEmpty(droneId)){droneId=Me.CubeGrid.CustomName;}}string GetDefaultConfig(){return @"[CargoShip]
; Unique drone identifier (defaults to grid name if blank)
DroneID=
; Home station -- must match your SupplyStation's StationID
HomeStation=CHANGE_ME
; Capability tags for station access matching (comma-separated)
Tags=
; Name substring to find SAM autopilot PB on this grid
AutopilotPBName=[SAM]
; LCD tag for status display
StatusLcdTag=[STATUS]
; Minimum battery charge % required before undocking (0 = disabled)
MinBatteryPercent=90
; Minimum hydrogen tank fill % required before undocking (0 = disabled)
MinH2Percent=90
; Toggle H2 tank Stockpile mode on dock/undock so tanks actually fill (true/false)
ManageH2Stockpile=true
; Turn thrusters off while docked -- stops idle H2 burn at the connector.
; Restored automatically during undock prep. (true/false)
ManageThrusters=true
; Batteries to Recharge while docked (one stays Auto as keep-alive),
; back to Auto for flight. (true/false)
ManageBatteries=true
; Ticks (Update100 ~= 1.6s each) to wait between stockpile-off and SAM autopilot
; trigger. Lets H2 repressurize conveyors before thrusters need fuel. Critical
; for heavy planet undocks. Set 0 to skip (only safe if you never stockpile).
UndockPrepTicks=2
";}void RunValidation(){validationErrors.Clear();validationFailed=false;if(string.IsNullOrEmpty(homeStation)||homeStation=="CHANGE_ME")validationErrors.Add("[CRITICAL] HomeStation not configured");if(string.IsNullOrEmpty(droneId))validationErrors.Add("[CRITICAL] DroneID could not be determined");var antennas=new List<IMyRadioAntenna>();GridTerminalSystem.GetBlocksOfType(antennas,a=>a.IsSameConstructAs(Me));if(antennas.Count==0){var lasers=new List<IMyLaserAntenna>();GridTerminalSystem.GetBlocksOfType(lasers,a=>a.IsSameConstructAs(Me));if(lasers.Count==0)validationErrors.Add("[CRITICAL] No antenna found -- IGC requires an antenna");}var connectors=new List<IMyShipConnector>();GridTerminalSystem.GetBlocksOfType(connectors,c=>c.IsSameConstructAs(Me));if(connectors.Count==0)validationErrors.Add("[CRITICAL] No connector found");if(autopilotPB==null)validationErrors.Add("[WARNING] SAM PB not found -- check AutopilotPBName");var cargo=new List<IMyCargoContainer>();GridTerminalSystem.GetBlocksOfType(cargo,c=>c.IsSameConstructAs(Me));if(cargo.Count==0)validationErrors.Add("[WARNING] No cargo containers on grid");if(GetThrusters().Count==0)validationErrors.Add("[WARNING] No thrusters on grid -- preflight will hold all launches");validationFailed=validationErrors.Exists(e=>e.Contains("[CRITICAL]"));}void LogStatus(string message){statusLog.AppendLine(message);}void UpdateDisplays(){Echo(statusLog.ToString());var surfaces=GetDisplaySurfaces(statusLcdTag);foreach(var surface in surfaces){surface.ContentType=ContentType.TEXT_AND_IMAGE;surface.WriteText(statusLog.ToString());}}List<IMyTextSurface>GetDisplaySurfaces(string tag){var result=new List<IMyTextSurface>();var panels=new List<IMyTextPanel>();GridTerminalSystem.GetBlocksOfType(panels,p=>p.IsSameConstructAs(Me)&&(p.CustomName.Contains(tag)||p.CustomData.Contains(tag)));foreach(var p in panels)result.Add(p);var blocks=new List<IMyTerminalBlock>();GridTerminalSystem.GetBlocksOfType(blocks,b=>b.IsSameConstructAs(Me)&&!(b is IMyTextPanel)&&b is IMyTextSurfaceProvider&&b.CustomData.Contains(tag));foreach(var block in blocks){var provider=(IMyTextSurfaceProvider)block;int idx=ParseSurfaceIndex(block.CustomData,tag);if(idx>=0&&idx<provider.SurfaceCount)result.Add(provider.GetSurface(idx));}return result;}int ParseSurfaceIndex(string customData,string tag){foreach(var line in customData.Split('\n')){var trimmed=line.Trim();if(trimmed==tag)return 0;if(trimmed.Length>tag.Length&&trimmed.StartsWith(tag)&&trimmed[tag.Length]==':'){int idx;if(int.TryParse(trimmed.Substring(tag.Length+1).Trim(),out idx))return idx;return 0;}}return 0;}
#endregion